import json,re
from pathlib import Path
headings={
'nucleic-acids':[
['DNA carries hereditary information in cells','RNA genomes in viruses are a separate case'],['Three components make a nucleotide','Connect the base and phosphate to the sugar'],['Covalent links build the sugar–phosphate backbone','Strand separation preserves the covalent backbone'],['Recognize the bases in DNA and RNA','Purines have two rings; pyrimidines have one'],['Ribonucleotides form an RNA chain','Distinguish a net model from polymerase chemistry'],['Two complementary strands run antiparallel','Represent pairing and strand orientation'],['Compare DNA with RNA','Locate the difference at the sugar’s 2′ carbon'],['Complementary pairing makes copying possible','Read the template in the correct direction'],['Count the possibilities in a base sequence','A finite molecule has finite information capacity'],['The genetic code maps codons to amino acids','Conservation supports common ancestry'],['Number the sugar and identify each end','Synthesis and reading have defined directions'],['Pair a purine with a pyrimidine','Complementary geometry maintains helix width'],['DNA wraps around a histone octamer','Inspect a nucleosome in a molecular viewer'],['Label phage DNA and protein separately','Interpret the pellet and supernatant evidence'],['Base ratios reveal a pattern','Induction and falsification do different jobs']],
'enzymes-metabolism':[
['Catalysts lower the activation barrier','Faster reactions do not imply a different equilibrium'],['Metabolism is a network of linked reactions','Specificity requires many different enzymes'],['Anabolism builds; catabolism breaks down','Couple reactions to an energy supply'],['A few residues form an active site','The rest of the protein supports its geometry'],['Binding can change enzyme and substrate shape','Induced fit is adjustment, not denaturation'],['Productive encounters require access and orientation','Immobilized enzymes can still encounter substrates'],['Chemical groups help determine specificity','Temperature and pH can disturb productive binding'],['Conditions change collision frequency and activity','Substrate saturation limits an initial rate'],['A rate is change per unit time','Use a tangent to estimate the initial rate'],['The transition state has an energy barrier','Compare catalysed and uncatalysed energy profiles'],['Reactions occur inside cells and outside them','Exocytosis delivers digestive enzymes outside'],['Energy transfers also release heat','Metabolic heat supports thermoregulation'],['Linear pathways have sequential intermediates','Cycles regenerate a participant while exchanging matter'],['Allosteric binding can alter catalytic activity','A school model does not describe every kinetic pattern'],['Competitive inhibitors obstruct substrate binding','Statins illustrate active-site competition'],['Isoleucine regulates its own biosynthetic pathway','Reversible feedback reduces unnecessary pathway flux'],['Penicillin targets bacterial crosslinking enzymes','Resistance can alter the target or destroy the antibiotic']],
'membranes-transport':[
['One phospholipid has two chemical regions','Bilayers put heads toward water and tails inward','A protein-free vesicle tests the lipid barrier'],['A hydrated ion faces an energetic barrier','Selective barriers allow distinct cellular conditions','Permeability depends on the particular solute'],['Small gases can cross by random molecular motion','Unequal opposing flows produce net diffusion','Oxygen exchange depends on more than a gradient'],['Integral and peripheral proteins occupy different locations','Location supports transport, signalling and attachment','Red-cell proteins combine exchange with resilience'],['Water crosses both bilayers and aquaporins','Unequal water potentials produce net movement','A cell’s surroundings can make it swell'],['A channel supplies a selective aqueous pathway','Electrochemical gradients drive passive ion flow','Open channels do not become ATP-driven pumps'],['Uphill transport needs an energy-coupled cycle','Alternating access distinguishes a pump from a pore','Plant H+-ATPases build useful proton gradients'],['Size, polarity and charge affect lipid permeability','Proteins add selective routes through the barrier','Compare two solutes before predicting entry'],['Carbohydrate chains face the noncytosolic side','Surface sugars support recognition and adhesion','ABO antigens illustrate a recognition pattern'],['A fluid bilayer supports a varied protein mosaic','Place each membrane component correctly','Fluidity preserves an organized barrier'],['Cis double bonds alter tail packing','Changing lipid composition helps cold adaptation','Lake sturgeon illustrate cold acclimation'],['Place cholesterol’s polar and nonpolar regions','Cholesterol buffers changes in membrane order','Animal membranes need useful fluidity'],['Endocytosis buds membrane inward','Exocytosis fuses a vesicle with the surface','Compare receptor uptake with hormone release'],['Ligand binding can open a channel','Voltage changes can gate a different channel','An open gate still obeys the ion gradient'],['The Na+/K+ pump exchanges three ions for two','An electrogenic cycle maintains useful gradients','Pump activity supports repeated nerve signalling'],['Sodium entry can drive glucose uptake','The sodium gradient depends indirectly on ATP','Locate coupled transport in absorptive epithelia'],['Adhesion molecules help neighbouring cells attach','Different junctions use different adhesion proteins','Epithelia depend on stable cell–cell connections']],
'cell-specialization':[
['A zygote develops into differently signalled cells','Position-dependent signals change gene expression','Interpret a morphogen concentration gradient'],['Stem cells self-renew and differentiate','Quiescence and division depend on tissue signals','Trace alternative daughter-cell fates'],['A niche is a regulatory microenvironment','Compare bone-marrow and hair-follicle niches','Signals and contacts maintain a stem-cell population'],['Potency describes the range of possible descendants','Adult multipotency is restricted to a lineage','Follow narrowing potential on a lineage tree'],['Cell dimensions reflect specialized functions','Compare a long axon with a long muscle fibre','Distinguish cell length from cell volume'],['Derive surface area and volume for a cube','Exchange surface must support internal demand','Explain why SA:V falls as a cell grows'],['Flattening shortens exchange distances','Projections and invaginations enlarge membrane area','Compare erythrocytes with kidney-tubule cells'],['Thin type I cells support gas diffusion','Type II cells release surface-active material','An alveolar wall works as a cooperative tissue'],['Cardiac cells connect; skeletal fibres extend','A skeletal fibre is one multinucleated cell','Relate branching and striation to function'],['A sperm cell combines motility with delivery','An oocyte supplies substantial cytoplasm','Connect each gamete structure with its role']]
}
corrections=[]
for slug,titles in headings.items():
 p=Path('src/biology/learning/'+slug+'/lesson.json');l=json.loads(p.read_text())
 for s,ts in zip(l['sections'],titles):
  assert len(ts)==len(s['teachingBlocks']),(slug,s['id'])
  for b,title in zip(s['teachingBlocks'],ts):b['title']=title
  for b in s['teachingBlocks']:
   old=b['explanation'];new=old.replace('As described in Hodder p. 237, cold acclimation','Cold acclimation').replace('Hodder printed p. 396 incorrectly says endocytosis in this context; independent NCBI digestive-enzyme evidence specifies exocytosis. ','').replace('Hodder printed p. 25 reverses the identity of the coding strand and the transcription template; LitLab deliberately corrects this error.','The coding strand is not the DNA template read by RNA polymerase.')
   if old!=new:corrections.append(dict(understanding=s['understandingIds'][0],oldEditorialNote=old,newStudentText=new));b['explanation']=new
  s['explanation']='\n\n'.join(b['explanation'] for b in s['teachingBlocks']);s['claimReferences']=[dict(claim=b['explanation'],referenceIds=b['referenceIds']) for b in s['teachingBlocks']]
 p.write_text(json.dumps(l,indent=2,ensure_ascii=False)+'\n')
Path('docs/biology/textbook-redesign/REMOVED_STUDENT_LOCATORS.json').write_text(json.dumps(corrections,indent=2,ensure_ascii=False)+'\n')
# Definitions improve the help tool without claiming a fresh chapter-depth rewrite.
definitions={'zygote':'cell formed by fusion of gametes','embryo':'an organism in early development','morphogen':'signal whose concentration can influence cell fate','gene expression':'use of genetic information to make a functional RNA or protein','differentiation':'development of specialized cellular features and functions','stem cell':'a cell capable of self-renewal and producing differentiated descendants','self-renewal':'production of descendants that retain stem-cell properties','potency':'range of cell types a cell can generate under suitable conditions','quiescence':'a relatively inactive, non-dividing state that can be reversible','niche':'local microenvironment regulating a stem-cell population','bone marrow':'tissue within bones containing blood-forming cells and their supporting environment','hematopoietic stem cell':'stem cell capable of producing multiple blood-cell lineages','hair follicle':'skin structure whose stem-cell populations contribute to hair growth','local signaling':'communication that influences nearby cells','totipotent':'able to contribute to all embryonic and necessary extraembryonic lineages','pluripotent':'able to produce the body’s cell types but not independently all necessary extraembryonic lineages','multipotent':'able to generate a restricted family of related cell types','blastomere':'a cell produced during early embryonic cleavage','inner cell mass':'group of cells inside a mammalian blastocyst that contributes to the embryo','erythrocyte':'red blood cell','oocyte':'female germ cell undergoing meiosis','spermatozoon':'a mature sperm cell','axon':'long projection carrying signals away from a neuron’s cell body','muscle fibre':'an elongated muscle cell','surface area':'area of the boundary of a structure','volume':'amount of three-dimensional space enclosed','SA:V ratio':'surface area divided by volume, with units of inverse length','square law':'area of a similar shape scales with the square of its linear dimension','cube law':'volume of a similar shape scales with the cube of its linear dimension','model assumption':'a stated simplification used to analyse a system','biconcave':'curved inward on both broad faces','microvilli':'short membrane projections that increase surface area','invagination':'an inward fold of a surface','proximal convoluted tubule':'early region of a kidney nephron involved in extensive reabsorption','alveolus':'a small air-exchange space in the lung','type I pneumocyte':'thin alveolar epithelial cell supporting short gas-diffusion distance','type II pneumocyte':'alveolar epithelial cell that secretes surfactant','lamellar body':'membrane-rich storage organelle associated with surfactant secretion','surfactant':'material that reduces surface tension at an interface','cardiomyocyte':'a cardiac muscle cell','striated muscle fibre':'a muscle cell with repeated contractile organization producing visible banding','myofibril':'contractile structure consisting of repeated sarcomeres','sarcomere':'a repeating contractile unit of striated muscle','intercalated disc':'specialized contact connecting cardiac muscle cells','syncytium':'a multinucleated continuous cellular unit','secondary oocyte':'female meiotic cell that in humans is ovulated while arrested in meiosis II','haploid':'having one set of chromosomes','acrosome':'sperm-head compartment with proteins involved in interactions during fertilization','zona pellucida':'glycoprotein layer surrounding a mammalian oocyte','flagellum':'long cellular projection that can support movement'}
p=Path('src/biology/learning/cell-specialization/lesson.json');l=json.loads(p.read_text())
for s in l['sections']:
 s['terms']=[t if ': ' in t else t+': '+definitions[t] for t in s['terms']]
 s['support']['concepts']=[dict(title=t.split(': ',1)[0],keywords=[k for k in re.findall(r'[a-z]+',t.split(': ',1)[0].lower()) if len(k)>2],explanation=t.split(': ',1)[1]+'. '+s['revisionSummary']) for t in s['terms']]
p.write_text(json.dumps(l,indent=2,ensure_ascii=False)+'\n')
